-- Vintora Wine Accessories catalogue target (PostgreSQL 15+ / Supabase).
-- Apply with: psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f sql/wine_accessories.sql
-- Internal staging domain under Vintora Market. RLS is enabled with no public policies.
-- Nulls are intentional; no licence, asset or price is generated by the database.

CREATE TABLE IF NOT EXISTS wine_accessories (
  sku                  text PRIMARY KEY,
  category             text NOT NULL CHECK (category IN (
    'Glassware', 'Decanters', 'Corkscrews', 'Aerators', 'Chillers',
    'Storage Racks', 'Preservation Systems', 'Gift Sets', 'Cleaning Tools'
  )),
  brand                text NOT NULL,
  product_name         text NOT NULL,
  materials            text[] NOT NULL DEFAULT '{}',
  dimensions           jsonb NOT NULL DEFAULT '{}'::jsonb,
  care_instructions    text[] NOT NULL DEFAULT '{}',
  tags                 text[] NOT NULL DEFAULT '{}',
  compliance_notes     jsonb NOT NULL DEFAULT '[]'::jsonb,
  msrp_usd             numeric(12,2) NOT NULL CHECK (msrp_usd >= 0),
  regional_prices      jsonb NOT NULL DEFAULT '[]'::jsonb,
  assets               jsonb NOT NULL DEFAULT '[]'::jsonb,
  official_image_url   text,
  backup_image_urls    text[] NOT NULL DEFAULT '{}',
  image_moderation     jsonb NOT NULL DEFAULT '{}'::jsonb,
  search_document      text NOT NULL DEFAULT '',
  search_keywords      text[] NOT NULL DEFAULT '{}',
  search_index         jsonb NOT NULL DEFAULT '{}'::jsonb,
  ai_enrichment        jsonb NOT NULL DEFAULT '{}'::jsonb,
  cross_sells          jsonb NOT NULL DEFAULT '[]'::jsonb,
  bundles              jsonb NOT NULL DEFAULT '[]'::jsonb,
  provenance           jsonb NOT NULL DEFAULT '{}'::jsonb,
  validation           jsonb NOT NULL DEFAULT '{}'::jsonb,
  audit_log            jsonb NOT NULL DEFAULT '[]'::jsonb,
  source               text GENERATED ALWAYS AS (provenance->>'source') STORED,
  moderation_status    text GENERATED ALWAYS AS (image_moderation->>'status') STORED,
  search_tsv           tsvector GENERATED ALWAYS AS (
    to_tsvector('english'::regconfig, coalesce(search_document, ''))
  ) STORED,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT wine_accessories_assets_array CHECK (jsonb_typeof(assets) = 'array'),
  CONSTRAINT wine_accessories_prices_array CHECK (jsonb_typeof(regional_prices) = 'array'),
  CONSTRAINT wine_accessories_moderation_check CHECK (
    image_moderation->>'status' IN ('approved', 'pending', 'rejected', 'missing')
  )
);

CREATE INDEX IF NOT EXISTS wine_accessories_category_idx
  ON wine_accessories (category, brand, product_name);
CREATE INDEX IF NOT EXISTS wine_accessories_source_moderation_idx
  ON wine_accessories (source, moderation_status);
CREATE INDEX IF NOT EXISTS wine_accessories_search_tsv_idx
  ON wine_accessories USING gin (search_tsv);
CREATE INDEX IF NOT EXISTS wine_accessories_tags_idx
  ON wine_accessories USING gin (tags);
CREATE INDEX IF NOT EXISTS wine_accessories_keywords_idx
  ON wine_accessories USING gin (search_keywords);
CREATE INDEX IF NOT EXISTS wine_accessories_provenance_idx
  ON wine_accessories USING gin (provenance jsonb_path_ops);
CREATE INDEX IF NOT EXISTS wine_accessories_assets_idx
  ON wine_accessories USING gin (assets jsonb_path_ops);
CREATE INDEX IF NOT EXISTS wine_accessories_ai_idx
  ON wine_accessories USING gin (ai_enrichment jsonb_path_ops);
CREATE INDEX IF NOT EXISTS wine_accessories_official_image_idx
  ON wine_accessories (official_image_url) WHERE official_image_url IS NOT NULL;

COMMENT ON TABLE wine_accessories IS
  'Wine Accessories catalogue staging. All commercial facts and image rights remain source-bound.';
COMMENT ON COLUMN wine_accessories.assets IS
  'Image assets with role, URL, licence, authorising party, authorisation reference and per-asset moderation.';
COMMENT ON COLUMN wine_accessories.search_tsv IS
  'Generated English full-text index over the source-bound search document.';
COMMENT ON COLUMN wine_accessories.ai_enrichment IS
  'Rule-based SEO, bundle and cross-sell suggestions labelled derived; no live model claim.';

CREATE TABLE IF NOT EXISTS wine_accessory_validation_rules (
  rule_id     text PRIMARY KEY,
  severity    text NOT NULL CHECK (severity IN ('error', 'warning')),
  description text NOT NULL,
  config      jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS wine_accessory_audit (
  id         bigserial PRIMARY KEY,
  sku        text NOT NULL,
  action     text NOT NULL CHECK (action IN ('create', 'ingested', 'deduplicated', 'insert', 'update', 'delete', 'import')),
  actor      text,
  source     text,
  reason     text,
  at         timestamptz NOT NULL DEFAULT now(),
  before     jsonb,
  after      jsonb,
  row_hash   text
);

CREATE INDEX IF NOT EXISTS wine_accessory_audit_sku_idx
  ON wine_accessory_audit (sku, at DESC);
CREATE INDEX IF NOT EXISTS wine_accessory_audit_action_idx
  ON wine_accessory_audit (action, at DESC);

COMMENT ON TABLE wine_accessory_audit IS
  'Append-only audit log for Wine Accessories catalogue writes.';

CREATE OR REPLACE FUNCTION wine_accessory_set_updated_at_fn()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS wine_accessory_set_updated_at_trg ON wine_accessories;
CREATE TRIGGER wine_accessory_set_updated_at_trg
  BEFORE UPDATE ON wine_accessories
  FOR EACH ROW EXECUTE FUNCTION wine_accessory_set_updated_at_fn();

CREATE OR REPLACE FUNCTION wine_accessory_audit_fn()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO wine_accessory_audit (sku, action, actor, source, reason, after, row_hash)
    VALUES (
      NEW.sku,
      'insert',
      COALESCE(NEW.provenance->>'actor', 'catalogue-import'),
      NEW.provenance->>'source',
      'row inserted',
      to_jsonb(NEW),
      md5(NEW.audit_log::text)
    );
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO wine_accessory_audit (sku, action, actor, source, reason, before, after, row_hash)
    VALUES (
      NEW.sku,
      'update',
      COALESCE(NEW.provenance->>'actor', 'catalogue-import'),
      NEW.provenance->>'source',
      'row updated',
      to_jsonb(OLD),
      to_jsonb(NEW),
      md5(NEW.audit_log::text)
    );
    RETURN NEW;
  ELSE
    INSERT INTO wine_accessory_audit (sku, action, actor, source, reason, before, row_hash)
    VALUES (
      OLD.sku,
      'delete',
      COALESCE(OLD.provenance->>'actor', 'catalogue-import'),
      OLD.provenance->>'source',
      'row deleted',
      to_jsonb(OLD),
      md5(OLD.audit_log::text)
    );
    RETURN OLD;
  END IF;
END;
$$;

DROP TRIGGER IF EXISTS wine_accessory_audit_trg ON wine_accessories;
CREATE TRIGGER wine_accessory_audit_trg
  AFTER INSERT OR UPDATE OR DELETE ON wine_accessories
  FOR EACH ROW EXECUTE FUNCTION wine_accessory_audit_fn();

CREATE OR REPLACE FUNCTION wine_accessory_audit_immutable_fn()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'wine_accessory_audit is append-only';
END;
$$;

DROP TRIGGER IF EXISTS wine_accessory_audit_immutable_trg ON wine_accessory_audit;
CREATE TRIGGER wine_accessory_audit_immutable_trg
  BEFORE UPDATE OR DELETE ON wine_accessory_audit
  FOR EACH ROW EXECUTE FUNCTION wine_accessory_audit_immutable_fn();

CREATE OR REPLACE VIEW wine_accessories_verified AS
SELECT *
FROM wine_accessories
WHERE source <> 'fixture'
  AND moderation_status = 'approved'
  AND COALESCE((validation->>'valid')::boolean, false) = true;

ALTER TABLE wine_accessories ENABLE ROW LEVEL SECURITY;
ALTER TABLE wine_accessory_validation_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE wine_accessory_audit ENABLE ROW LEVEL SECURITY;
